tool_input.new_string:
opinionLabel() {
  // 目标审批节点优先后端传回的 state，未传时回退到当前状态 status
  const node = this.state || this.status
  // 发改/资规/城调（区级部门）对应各自小组意见
  const departmentNodeMap = {
    userTask6: '发改小组意见',
    userTask7: '资规小组意见',
    userTask8: '城调小组意见'
  }
  if (departmentNodeMap[node]) {
    return departmentNodeMap[node]
  }
  // 市级领导小组节点（含以 status 判定的市级办理）
  if (['userTask3', 'userTask4', 'userTask9'].includes(node) || ['userTask3', 'userTask4', 'userTask9'].includes(this.status)) {
    return '市级领导小组意见'
  }
  return '区县领导小组意见'
},

